SELECT ?point ?ts WHERE {
  ?zone brick:hasName "Perimeter_bot_ZN_2" .
  ?point ref:hasExternalReference ?ts ;
         brick:isTypeOf brick:AirTemperature .
  FILTER(?zone ref:hasTimeseriesId ?ts || ?point brick:isPartOf* ?zone)
}

SELECT ?ts WHERE {
  ?z rdfs:label "Perimeter_bot_ZN_2" .
  ?point brick:isPointOf ?z ;
         brick:isTypeOf brick:AirTemperatureSensor .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?type ?ts WHERE {
  ?point a ?type .
  FILTER(str(?point) = "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z03.Zone_Air_Temperature_Sensor") .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
}

